begin;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('b11a0000-0000-4000-8000-000000000001','authenticated','authenticated','quality-a@example.test','',now(),'{}','{"name":"Quality QA A","company_name":"Quality QA A"}',now(),now()),
('b11a0000-0000-4000-8000-000000000002','authenticated','authenticated','quality-b@example.test','',now(),'{}','{"name":"Quality QA B","company_name":"Quality QA B"}',now(),now());
select set_config('request.jwt.claims','{"sub":"b11a0000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into public.customers(id,company_id,name,document,phone,email,address,tags,notes) values('j-customer',private.current_company_id(),'Cliente QA','', '81900000000','qa@example.test','{}','{}','QA');
insert into public.products(id,company_id,name,pricing_type,base_cost,sales_price,stock_controlled,current_stock,min_stock) values('j-material',private.current_company_id(),'Material QA','unidade',2,5,true,10,0);
insert into public.orders(id,company_id,customer_id,customer_name,number,status,total_amount,paid_amount,payment_status,shipping_cost,deadline,notes) values('j-order',private.current_company_id(),'j-customer','Cliente QA','PED-11J','producao',100,0,'pendente',0,now()+interval '2 days','QA');
insert into public.order_items(id,order_id,product_name,quantity,unit_price,total_price,details) values('j-item','j-order','Item QA',10,10,100,'{}');
insert into public.production_queue(id,company_id,order_id,order_number,order_item_id,product_name,quantity,status) values('j-queue',private.current_company_id(),'j-order','PED-11J','j-item','Item QA',10,'concluido');
create function pg_temp.nc(a text,patch jsonb default '{}') returns jsonb language sql as $$select public.quality_command(gen_random_uuid(),a,(select jsonb_build_object('id',id,'updated_at',updated_at,'cost_version',private.quality_cost_version(id)) from public.quality_nonconformities where id=current_setting('quality.id')::uuid)||patch)$$;
select set_config('quality.origin',private.quality_origin(private.current_company_id(),'production','j-queue')::text,true);
select set_config('quality.payload',jsonb_build_object('source_type','production','source_id','j-queue','source_updated_at',current_setting('quality.origin')::jsonb->>'version','description','Impressão com defeito em parte do lote','category','print_defect','severity','critical','affected_quantity',2,'assigned_profile_id',(select id from public.profiles where auth_user_id=auth.uid()),'cost_applicable',true)::text,true);
select set_config('quality.operation',gen_random_uuid()::text,true);
select set_config('quality.id',public.quality_command(current_setting('quality.operation')::uuid,'create',current_setting('quality.payload')::jsonb)->>'id',true);
select is((select number from public.quality_nonconformities where id=current_setting('quality.id')::uuid),1::bigint,'tenant sequence');
select is(public.quality_command(current_setting('quality.operation')::uuid,'create',current_setting('quality.payload')::jsonb)->>'id',current_setting('quality.id'),'idempotent create');
set local role authenticated;
select is(public.save_order_with_items_and_production((select to_jsonb(o) from public.orders o where id='j-order'),(select jsonb_agg(to_jsonb(i)||jsonb_build_object('details',i.details||'{"notes":"Observação operacional permanece editável"}'::jsonb)) from public.order_items i where order_id='j-order'),(select updated_at from public.orders where id='j-order'))->>'result_status','UPDATED','canonical Order UPSERT keeps details.notes editable with NC');
select is(public.save_order_with_items_and_production((select to_jsonb(o)||'{"total_amount":110}'::jsonb from public.orders o where id='j-order'),(select jsonb_agg(to_jsonb(i)||'{"unit_price":11,"total_price":110}'::jsonb) from public.order_items i where order_id='j-order'),(select updated_at from public.orders where id='j-order'))->>'result_status','UPDATED','explicit commercial correction does not rewrite technical history');
reset role;
select throws_like($$update public.order_items set details=details||'{"width":2}' where id='j-item'$$,'%configuração técnica%','physical configuration remains protected');
select throws_like($$select pg_temp.nc('close')$$,'%causa%','closure requires cause and action');
select lives_ok($$select pg_temp.nc('analyze','{"root_cause":"Ajuste de impressão incorreto","analysis":"Conferência sintética do lote","problem_origin":"internal"}')$$,'record root cause');
select lives_ok($$select pg_temp.nc('action_define',jsonb_build_object('kind','rework','execution_mode','internal','quantity',2,'assigned_profile_id',(select id from public.profiles where auth_user_id=auth.uid()),'notes','Refazer somente duas unidades afetadas'))$$,'define partial rework');
select lives_ok($$select pg_temp.nc('action_start',jsonb_build_object('production_updated_at',(select updated_at from public.production_queue where id='j-queue')))$$,'restart same canonical queue explicitly');
select is((select count(*) from public.production_queue where order_id='j-order'),1::bigint,'no parallel queue');
select is((select quantity from public.order_items where id='j-item'),10::numeric,'commercial quantity preserved');
select is((select quantity from public.production_queue where id='j-queue'),2::numeric,'partial execution quantity');
select is((select execution_number from public.production_queue where id='j-queue'),2,'new execution number');
select is((select (snapshot->>'quantity')::numeric from public.production_executions where production_id='j-queue' and execution_number=1),10::numeric,'original execution preserved');
select throws_like($$update public.production_queue set status='concluido' where id='j-queue'$$,'%NC crítica/bloqueante%','critical NC blocks completion');
update public.production_queue set status='producao',started_at=now() where id='j-queue';
select lives_ok($$select pg_temp.nc('material_consume','{"product_id":"j-material","quantity":2}')$$,'canonical additional material');
select is((select current_stock from public.products where id='j-material'),8::numeric,'one stock debit');
select throws_like($$select pg_temp.nc('material_consume','{"product_id":"j-material","quantity":2}')$$,'%já consumido%','another nonce cannot duplicate active consumption');
select is((private.quality_cost_summary(current_setting('quality.id')::uuid)->>'actual')::numeric,4::numeric,'actual reference cost');
select lives_ok($$select pg_temp.nc('action_finish','{"result":"Duas unidades refeitas e conferidas"}')$$,'record physical result');
select is((select status from public.production_queue where id='j-queue'),'producao','result never silently concludes queue');
select throws_like($$select pg_temp.nc('close')$$,'%Reinspeção aprovada%','reinspection required');
select lives_ok($$select pg_temp.nc('reinspect','{"result":"rejected","notes":"Segunda amostra ainda apresenta desvio"}')$$,'failed inspection');
select throws_like($$select pg_temp.nc('close')$$,'%causa%','failed action cannot close');
select lives_ok($$select pg_temp.nc('action_define',jsonb_build_object('kind','adjustment','execution_mode','none','quantity',2,'assigned_profile_id',(select id from public.profiles where auth_user_id=auth.uid()),'notes','Conferir e ajustar as duas unidades'))$$,'new action version after failure');
select lives_ok($$select pg_temp.nc('action_start')$$,'start second action');
select lives_ok($$select pg_temp.nc('action_finish','{"result":"Ajuste concluído e amostra estável"}')$$,'finish adjustment');
select lives_ok($$select pg_temp.nc('reinspect','{"result":"approved","notes":"Amostra e medidas conformes após ajuste"}')$$,'positive inspection');
select set_config('quality.old_cost_version',private.quality_cost_version(current_setting('quality.id')::uuid),true);
update public.production_queue set priority='alta' where id='j-queue';
select throws_like($$select pg_temp.nc('close',jsonb_build_object('cost_version',current_setting('quality.old_cost_version')))$$,'%Execuções ou apuração mudaram%','closure also compares facts changed in canonical modules');
select lives_ok($$select pg_temp.nc('close')$$,'close with actual cost');
select is((select (cost_snapshot->>'actual')::numeric from public.quality_closures where nc_id=current_setting('quality.id')::uuid),4::numeric,'closure snapshots actual cost');
select lives_ok($$update public.production_queue set status='concluido' where id='j-queue'$$,'resolved NC permits explicit completion');
select is((select status from public.orders where id='j-order'),'producao','Order status remains independent');
select lives_ok($$select pg_temp.nc('material_reverse',jsonb_build_object('material_id',(select id from public.quality_materials where nc_id=current_setting('quality.id')::uuid),'reason','Reversão física da fixture QA'))$$,'cleanup by inverse movement');
select is((select current_stock from public.products where id='j-material'),10::numeric,'stock restored');
select is((select (cost_snapshot->>'actual')::numeric from public.quality_closures where nc_id=current_setting('quality.id')::uuid),4::numeric,'reversal cannot rewrite closure');
select is((public.quality_source(current_date,current_date,current_setting('quality.id')::uuid)#>>array['summaries',current_setting('quality.id'),'actual'])::numeric,4::numeric,'read model keeps frozen closed cost after inverse movement');
select lives_ok($$select pg_temp.nc('reopen','{"reason":"Novo ciclo de verificação sintética"}')$$,'restricted reopening');
select is((select cycle from public.quality_nonconformities where id=current_setting('quality.id')::uuid),2,'new cycle preserves previous history');
select lives_ok($$select pg_temp.nc('cost_save',jsonb_build_object('action_id',(select id from public.quality_actions where nc_id=current_setting('quality.id')::uuid order by version desc limit 1),'kind','labor','description','Previsão ainda não apurada QA','planned',10,'actual',null))$$,'missing actual remains an explicit pending fact');
select is(private.quality_cost_summary(current_setting('quality.id')::uuid)->>'actual',null::text,'no informed actual is never fabricated as zero');
select lives_ok($$select pg_temp.nc('cost_save',jsonb_build_object('cost_id',(select id from public.quality_costs where nc_id=current_setting('quality.id')::uuid),'kind','labor','description','Sem gasto efetivo na fixture QA','planned',10,'actual',0,'reason','Apuração sintética confirma ausência de gasto'))$$,'explicit zero is distinguishable from missing actual');
select is((private.quality_cost_summary(current_setting('quality.id')::uuid)->>'actual')::numeric,0::numeric,'explicit zero is a known fact');
select lives_ok($$select pg_temp.nc('cancel','{"reason":"Encerrar fixture sintética QA"}')$$,'cancel zero-exposure fixture');
select lives_ok($$select public.quality_source(current_date,current_date,current_setting('quality.id')::uuid)$$,'detail read model composes canonical history');
select lives_ok($$select public.quality_source(current_date,current_date)$$,'period read model and cohort');
select lives_ok($$select public.quality_origins('order')$$,'search Orders');
select lives_ok($$select public.quality_origins('production')$$,'search canonical queues');
select lives_ok($$select public.quality_origins('purchase')$$,'search Purchases');
select lives_ok($$select public.quality_origins('receipt')$$,'search Receipts');
select lives_ok($$select public.quality_origins('outsourcing')$$,'search OTs');
select lives_ok($$select public.quality_origins('field_service')$$,'search Field Services');
select is(jsonb_array_length(public.quality_links('production',array['j-queue'])->'links'),1,'batched canonical Production link');
select set_config('request.jwt.claims','{"sub":"b11a0000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*) from public.quality_nonconformities),0::bigint,'tenant B cannot read A');
select throws_like($$select public.quality_command(gen_random_uuid(),'reopen',jsonb_build_object('id',current_setting('quality.id'),'updated_at',now(),'reason','Outro tenant'))$$,'%indisponível%','tenant B cannot mutate A');
reset role;
select * from finish();rollback;
